 @Test void deniedBoundedScanCanReturnEmptyPageWithOpaqueNext()throws Exception{grant=grant("DOCUMENT_BODY",null);var second=changed(row,"auditId",id(39));var third=changed(row,"auditId",id(38));when(mapper.scan(anyMap())).thenReturn(List.of(row,second,third));var p=page();assertEquals(0,p.path("items").size());assertFalse(p.path("complete").asBoolean());assertFalse(p.path("next_cursor").isNull());assertFalse(p.path("next_cursor").asText().contains(id(39)));verify(mapper,never()).payload(anyMap());}
