 @Test void cursorBindsEveryOwnerFieldAndExpires()throws Exception{var clock=mock(Clock.class);when(clock.instant()).thenReturn(Instant.parse("2026-10-18T12:00:00Z"));var store=new BusinessAuditCursor(policy,clock);var owner=new BusinessAuditCursor.Owner(id(1),id(2),id(3),"1","1","1",HASH);var position=new BusinessAuditCursor.Position(now,id(40));String token=store.issue(owner,position);assertEquals(position,store.resolve(token,owner));for(String field:List.of("tenant","actor","session","context","auth","governance","queryHash"))assertEquals(ErrorCode.CURSOR_INVALID,assertThrows(TenantAccessException.class,()->store.resolve(token,changed(owner,field,"different"))).code());when(clock.instant()).thenReturn(Instant.parse("2026-10-18T12:01:00Z"));assertEquals(ErrorCode.CURSOR_EXPIRED,assertThrows(TenantAccessException.class,()->store.resolve(token,owner)).code());}
