 @Test void actualRuntimeSqlMapsBindEveryExecutedPlaceholder()throws Exception{
  page();var configuration=new org.apache.ibatis.session.Configuration();try(var input=java.util.Objects.requireNonNull(getClass().getResourceAsStream("/medical-mappers/BusinessAuditMapper.xml"))){new org.apache.ibatis.builder.xml.XMLMapperBuilder(input,configuration,"BusinessAuditMapper.xml",configuration.getSqlFragments()).parse();}
  Set<String> methods=new HashSet<>();for(var invocation:mockingDetails(mapper).getInvocations()){String method=invocation.getMethod().getName();methods.add(method);var values=(Map<?,?>)invocation.getArgument(0);assertEquals(id(2),values.get("userId"));var sql=configuration.getMappedStatement("com.ruoyi.medical.persistence.mapper.BusinessAuditMapper."+method).getBoundSql(values);for(var parameter:sql.getParameterMappings())assertNotNull(configuration.newMetaObject(values).getValue(parameter.getProperty()),method+":"+parameter.getProperty());}assertEquals(Set.of("scan","payload","operation","operationResponse","target"),methods);
 }
